-- Fixed StepType handlers are defined in the Java enum, never seeded as rows.


CREATE TEMPORARY TABLE `WorkflowSeedStep` (
    `workflow_code` VARCHAR(80), `workflow_id` BINARY(16), `task_code` VARCHAR(80), `step_code` VARCHAR(80),
    `step_type_code` VARCHAR(40), `sequence_no` INT, `timeout_sec` INT, `audit_level` VARCHAR(16)
);


SELECT UNHEX(MD5(CONCAT(s.workflow_code,':STEP:',s.step_code))),s.workflow_id,UNHEX(MD5(CONCAT(s.workflow_code,':TASK:',s.task_code))),s.step_type_code,s.step_code,REPLACE(s.step_code,'_',' '),s.sequence_no,TRUE,JSON_OBJECT(),JSON_OBJECT(),s.timeout_sec,1,0,JSON_ARRAY(),1,s.audit_level,UTC_TIMESTAMP(6)
FROM `WorkflowSeedStep` s;

-- INTERACT is Server-orchestrated and requires a stable prompt key per the Step Type contract.
UPDATE `Step` SET `params_json`=JSON_OBJECT('prompt_key',`step_code`)
WHERE `step_type_code`='INTERACT' AND JSON_LENGTH(`params_json`)=0;

UPDATE `Workflow` SET `start_step_id`=UNHEX(MD5('WF_PATIENT_ESCORT:STEP:CONFIRM')) WHERE `workflow_code`='WF_PATIENT_ESCORT' AND `version_no`=3;
UPDATE `Workflow` SET `start_step_id`=UNHEX(MD5('WF_INFORMATION_ASSISTANCE:STEP:QUERY')) WHERE `workflow_code`='WF_INFORMATION_ASSISTANCE' AND `version_no`=3;
UPDATE `Workflow` SET `start_step_id`=UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:STEP:PICKUP')) WHERE `workflow_code`='WF_SECURE_MEDICAL_DELIVERY' AND `version_no`=3;
UPDATE `Workflow` SET `start_step_id`=UNHEX(MD5('WF_EMERGENCY_SOS_RESPONSE:STEP:ALERT')) WHERE `workflow_code`='WF_EMERGENCY_SOS_RESPONSE' AND `version_no`=3;

CREATE TEMPORARY TABLE `WorkflowSeedRoute` (
    `workflow_code` VARCHAR(80), `workflow_id` BINARY(16), `step_code` VARCHAR(80),
    `success_target` VARCHAR(80) NULL, `success_terminal` VARCHAR(32) NULL,
    `condition_target` VARCHAR(80) NULL, `condition_json` JSON NULL,
    `failure_target` VARCHAR(80) NULL, `failure_terminal` VARCHAR(32) NULL,
    `timeout_target` VARCHAR(80) NULL, `timeout_terminal` VARCHAR(32) NULL
);


SELECT UNHEX(MD5(CONCAT(r.workflow_code,':TRANSITION:',r.step_code,':SUCCESS:CONDITION'))),r.workflow_id,
       UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.step_code))),UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.condition_target))),
       'SUCCESS',r.condition_json,1,FALSE,NULL FROM `WorkflowSeedRoute` r WHERE r.condition_target IS NOT NULL;

SELECT UNHEX(MD5(CONCAT(r.workflow_code,':TRANSITION:',r.step_code,':SUCCESS:DEFAULT'))),r.workflow_id,
       UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.step_code))),
       CASE WHEN r.success_target IS NULL THEN NULL ELSE UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.success_target))) END,
       'SUCCESS',CASE WHEN r.condition_target IS NULL THEN 1 ELSE 2 END,TRUE,r.success_terminal FROM `WorkflowSeedRoute` r;

SELECT UNHEX(MD5(CONCAT(r.workflow_code,':TRANSITION:',r.step_code,':FAILURE:DEFAULT'))),r.workflow_id,
       UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.step_code))),
       CASE WHEN r.failure_target IS NULL THEN NULL ELSE UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.failure_target))) END,
       'FAILURE',1,TRUE,r.failure_terminal FROM `WorkflowSeedRoute` r;

SELECT UNHEX(MD5(CONCAT(r.workflow_code,':TRANSITION:',r.step_code,':TIMEOUT:DEFAULT'))),r.workflow_id,
       UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.step_code))),
       CASE WHEN r.timeout_target IS NULL THEN NULL ELSE UNHEX(MD5(CONCAT(r.workflow_code,':STEP:',r.timeout_target))) END,
       'TIMEOUT',1,TRUE,r.timeout_terminal FROM `WorkflowSeedRoute` r;

DROP TEMPORARY TABLE `WorkflowSeedRoute`;
DROP TEMPORARY TABLE `WorkflowSeedStep`;

-- Complete the eight standard workflows from the Draw.io business diagrams.
UPDATE `Workflow` SET start_step_id=UNHEX(MD5('WF_CROWD_MONITORING:STEP:INIT')) WHERE workflow_id=UNHEX(MD5('WF_CROWD_MONITORING:WORKFLOW:1'));
UPDATE `Workflow` SET start_step_id=UNHEX(MD5('WF_FALL_RESPONSE:STEP:CHECK_CONFIDENCE')) WHERE workflow_id=UNHEX(MD5('WF_FALL_RESPONSE:WORKFLOW:1'));
UPDATE `Workflow` SET start_step_id=UNHEX(MD5('WF_RESTRICTED_MONITORING:STEP:MOVE')) WHERE workflow_id=UNHEX(MD5('WF_RESTRICTED_MONITORING:WORKFLOW:1'));
UPDATE `Workflow` SET start_step_id=UNHEX(MD5('WF_NAVIGATION:STEP:IS_GROUP')) WHERE workflow_id=UNHEX(MD5('WF_NAVIGATION:WORKFLOW:1'));
UPDATE `Workflow` SET start_step_id=NULL WHERE workflow_id=UNHEX(REPLACE('10000000-0000-0000-0000-000000000004','-',''));
DELETE FROM `StepTransition` WHERE workflow_id=UNHEX(REPLACE('10000000-0000-0000-0000-000000000004','-',''));
DELETE FROM `Step` WHERE workflow_id=UNHEX(REPLACE('10000000-0000-0000-0000-000000000004','-',''));
UPDATE `Workflow` SET start_step_id=UNHEX(MD5('WF_EMERGENCY_SOS_RESPONSE:STEP:ALERT')) WHERE workflow_id=UNHEX(REPLACE('10000000-0000-0000-0000-000000000004','-',''));

-- Delivery acknowledgement after sender-side physical verification.
UPDATE `Step` SET sequence_no=sequence_no+1 WHERE workflow_id=UNHEX(REPLACE('10000000-0000-0000-0000-000000000003','-','')) AND sequence_no>=12 ORDER BY sequence_no DESC;
VALUES (UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:STEP:COMPLETE_PICKUP')),UNHEX(REPLACE('10000000-0000-0000-0000-000000000003','-','')),UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:TASK:PICKUP')),'NOTIFY','COMPLETE_PICKUP','Complete pickup',12,TRUE,JSON_OBJECT('notification_type','COMPLETE_PICKUP','recipients',JSON_ARRAY()),JSON_OBJECT(),60,1,0,JSON_ARRAY(),1,'FULL',UTC_TIMESTAMP(6));
UPDATE `StepTransition` SET to_step_id=UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:STEP:COMPLETE_PICKUP')) WHERE from_step_id=UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:STEP:CHECK_LOCK_SENDER')) AND to_step_id=UNHEX(MD5('WF_SECURE_MEDICAL_DELIVERY:STEP:TRANSIT'));

-- Insert edges only after every referenced Step has been created.
